  "inlineSchema": "// LPM — 日志与项目管理系统 · 数据库模型（SQLite）\n// 说明：SQLite 不支持 @db.Uuid / @db.VarChar，Json 一律用 String 存 JSON 文本\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  // native = 本机（Linux，开发自测用）\n  // windows = 目标机（Windows 离线包用，必须一起生成，否则拷过去跑不起来）\n  binaryTargets = [\"native\", \"windows\"]\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n/// 工作表元数据（永久工作表栏的数据源）\nmodel TableMeta {\n  id         String    @id @default(uuid())\n  name       String\n  type       String    @default(\"log\") // log | project | people\n  config     String    @default(\"{}\")\n  sort_order Int       @default(0)\n  created_at DateTime  @default(now())\n  updated_at DateTime  @updatedAt\n  deleted_at DateTime?\n\n  @@map(\"tables_meta\")\n}\n\n/// 日志条目（周日历里每一天一格）\nmodel LogEntry {\n  id         String   @id @default(uuid())\n  table_id   String\n  entry_date String // YYYY-MM-DD\n  content    String   @default(\"\")\n  created_by String?\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@unique([table_id, entry_date])\n  @@index([table_id, entry_date])\n  @@map(\"log_entries\")\n}\n\n/// 待办\nmodel Todo {\n  id                String    @id @default(uuid())\n  table_id          String\n  title             String\n  assignee_id       String?\n  points            Int       @default(0)\n  status            String    @default(\"pending\") // pending | done\n  record_time       DateTime  @default(now())\n  completed_at      DateTime?\n  sort_order        Int       @default(0)\n  linked_project_id String?\n  linked_task_id    String?\n  transferred       Boolean   @default(false)\n  note              String?\n  created_at        DateTime  @default(now())\n  updated_at        DateTime  @updatedAt\n  deleted_at        DateTime?\n\n  @@index([table_id, status])\n  @@map(\"todos\")\n}\n\n/// 项目\nmodel Project {\n  id          String    @id @default(uuid())\n  table_id    String\n  name        String\n  description String?\n  start_date  String?\n  end_date    String?\n  status      String    @default(\"active\") // active | done | paused\n  created_at  DateTime  @default(now())\n  updated_at  DateTime  @updatedAt\n  deleted_at  DateTime?\n\n  @@map(\"projects\")\n}\n\n/// 项目任务（含计划/实际/进度/积分）\nmodel ProjectTask {\n  id            String    @id @default(uuid())\n  project_id    String\n  parent_id     String?\n  name          String\n  plan_start    String?\n  plan_duration Int       @default(1)\n  plan_end      String?\n  actual_start  String?\n  actual_end    String?\n  progress      Int       @default(0)\n  assignee_id   String?\n  points        Int       @default(0)\n  earned_points Float     @default(0)\n  status        String    @default(\"not_started\") // not_started | in_progress | done | delayed\n  sort_order    Int       @default(0)\n  note          String?\n  created_at    DateTime  @default(now())\n  updated_at    DateTime  @updatedAt\n  deleted_at    DateTime?\n\n  @@index([project_id])\n  @@map(\"project_tasks\")\n}\n\n/// 人员\nmodel Person {\n  id           String    @id @default(uuid())\n  name         String\n  role         String?\n  color        String?\n  total_points Float     @default(0)\n  created_at   DateTime  @default(now())\n  updated_at   DateTime  @updatedAt\n  deleted_at   DateTime?\n\n  @@map(\"people\")\n}\n\n/// 积分流水（唯一的积分真相来源）\nmodel PointsLedger {\n  id          String   @id @default(uuid())\n  person_id   String\n  person_name String?\n  source_type String // todo | project_task | manual\n  source_id   String?\n  points      Float\n  reason      String?\n  created_at  DateTime @default(now())\n\n  @@index([person_id])\n  @@map(\"points_ledger\")\n}\n\n/// 操作历史（可追溯、可回滚的依据）\nmodel ChangeHistory {\n  id         String   @id @default(uuid())\n  table_id   String?\n  record_id  String?\n  entity     String?\n  action     String // create | update | delete | complete\n  before     String?\n  after      String?\n  changed_by String?\n  created_at DateTime @default(now())\n\n  @@index([table_id, created_at])\n  @@map(\"change_history\")\n}\n\n/// 提醒（日志页格子里的\"提前写好的文字\"）\n///   repeat: once | weekly | monthly | yearly\n///   rule  : JSON 文本，随 repeat 变化\n///           once    → {\"date\":\"2026-10-15\"}\n///           weekly  → {\"weekdays\":[1,3,5]}          （1=周一 … 7=周日）\n///           monthly → {\"days\":[1,15]}                （每月几号）\n///           yearly  → {\"dates\":[{\"month\":10,\"day\":8}]}\n///   start_date / end_date：生效范围（含两端；为空=不限）\nmodel Reminder {\n  id         String    @id @default(uuid())\n  table_id   String\n  text       String\n  repeat     String    @default(\"once\")\n  rule       String    @default(\"{}\")\n  start_date String?\n  end_date   String?\n  enabled    Boolean   @default(true)\n  color      String?\n  sort_order Int       @default(0)\n  created_at DateTime  @default(now())\n  updated_at DateTime  @updatedAt\n  deleted_at DateTime?\n\n  @@index([table_id])\n  @@map(\"reminders\")\n}\n\n/// 导入导出任务记录\nmodel ImportExportJob {\n  id         String   @id @default(uuid())\n  kind       String // import | export\n  status     String   @default(\"done\")\n  detail     String?\n  created_at DateTime @default(now())\n\n  @@map(\"import_export_jobs\")\n}\n",
